<?php require_once __DIR__.'/../app/bootstrap.php'; $u=require_login();$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM reading_plans WHERE id=? AND user_id=?');$st->execute([$id,$u['id']]);$p=$st->fetch()?:die('未找到'); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$x=$_POST;db()->prepare('UPDATE reading_plans SET name=?,plan_type=?,start_date=?,end_date=?,target_count=?,description=?,status=? WHERE id=? AND user_id=?')->execute([$x['name'],$x['plan_type'],$x['start_date'],$x['end_date'],(int)$x['target_count'],$x['description']?:null,$x['status'],$id,$u['id']]);redirect('plan_detail.php?id='.$id);} $title='编辑计划';include __DIR__.'/../app/layout/header.php';?><div class="card"><form method="post"><?=csrf_field()?><div class="form-grid"><div><label>计划名称</label><input name="name" value="<?=e($p['name'])?>"></div><div><label>类型</label><select name="plan_type"><?php foreach(['weekly'=>'周度','monthly'=>'月度','quarterly'=>'季度','yearly'=>'年度'] as $k=>$v):?><option value="<?=$k?>" <?=$p['plan_type']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div><label>状态</label><select name="status"><?php foreach(['not_started'=>'未开始','active'=>'进行中','completed'=>'已完成','failed'=>'未完成','cancelled'=>'已取消'] as $k=>$v):?><option value="<?=$k?>" <?=$p['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div><label>开始</label><input type="date" name="start_date" value="<?=e($p['start_date'])?>"></div><div><label>结束</label><input type="date" name="end_date" value="<?=e($p['end_date'])?>"></div><div><label>目标</label><input type="number" name="target_count" value="<?=e($p['target_count'])?>"></div></div><p><label>说明</label><textarea name="description"><?=e($p['description'])?></textarea></p><button>保存</button></form></div><?php include __DIR__.'/../app/layout/footer.php';?>
